def sequentialthinking(thought, nextThoughtNeeded, thoughtNumber, totalThoughts, isRevision=None, revisesThought=None, branchFromThought=None, branchId=None, needsMoreThoughts=None, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0551000" if __import__("os").path.isdir("./environment_mix/0551000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _C32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid():
        ms = int(time.time() * 1000)
        t = ms
        out = []
        for _ in range(10):
            out.append(_C32[t & 31])
            t >>= 5
        ts = "".join(reversed(out))
        r = random.getrandbits(80)
        out = []
        for _ in range(16):
            out.append(_C32[r & 31])
            r >>= 5
        rs = "".join(reversed(out))
        return ts + rs

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _norm_branch(b):
        if b is None:
            return None
        if not isinstance(b, str):
            return "__invalid__"
        b2 = b.strip()
        return b2 if b2 else None

    def _rate_limited(request_logs, api_key_id, rpm_limit):
        if not isinstance(rpm_limit, int) or rpm_limit < 1:
            return True
        now = datetime.datetime.now(datetime.timezone.utc)
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in request_logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            ts = _parse_iso(r.get("created_at"))
            if ts is None:
                continue
            if window_start <= ts <= now:
                cnt += 1
        return cnt >= rpm_limit

    def _active_sessions_count(sessions, api_key_id):
        c = 0
        for s in sessions:
            if isinstance(s, dict) and s.get("api_key_id") == api_key_id and s.get("status") == "active":
                c += 1
        return c

    start = time.time()
    now_iso = _now_iso()

    # Validate inputs
    if not isinstance(thought, str) or not thought.strip():
        return _err("VALIDATION_ERROR", "Invalid 'thought': must be a non-empty string.")
    if not isinstance(nextThoughtNeeded, bool):
        return _err("VALIDATION_ERROR", "Invalid 'nextThoughtNeeded': must be boolean.")
    if not isinstance(thoughtNumber, int) or thoughtNumber < 1:
        return _err("VALIDATION_ERROR", "Invalid 'thoughtNumber': must be an integer >= 1.")
    if not isinstance(totalThoughts, int) or totalThoughts < 1:
        return _err("VALIDATION_ERROR", "Invalid 'totalThoughts': must be an integer >= 1.")
    if isRevision is not None and not isinstance(isRevision, bool):
        return _err("VALIDATION_ERROR", "Invalid 'isRevision': must be boolean if provided.")
    if revisesThought is not None and (not isinstance(revisesThought, int) or revisesThought < 1):
        return _err("VALIDATION_ERROR", "Invalid 'revisesThought': must be an integer >= 1 if provided.")
    if branchFromThought is not None and (not isinstance(branchFromThought, int) or branchFromThought < 1):
        return _err("VALIDATION_ERROR", "Invalid 'branchFromThought': must be an integer >= 1 if provided.")
    if needsMoreThoughts is not None and not isinstance(needsMoreThoughts, bool):
        return _err("VALIDATION_ERROR", "Invalid 'needsMoreThoughts': must be boolean if provided.")
    bnorm = _norm_branch(branchId)
    if bnorm == "__invalid__":
        return _err("VALIDATION_ERROR", "Invalid 'branchId': must be a string if provided.")

    # Enforce revision constraints from schema
    if isRevision is True and revisesThought is None:
        return _err("VALIDATION_ERROR", "Invalid revision: 'revisesThought' is required when 'isRevision' is true.")
    if isRevision is False and revisesThought is not None:
        return _err("VALIDATION_ERROR", "Invalid revision: 'revisesThought' must be omitted when 'isRevision' is false.")

    api_keys = _load("api_keys.json")
    sessions = _load("thinking_sessions.json")
    thought_events = _load("thought_events.json")
    branches = _load("branches.json")
    request_logs = _load("request_logs.json")

    # Ambient auth: choose an active key that can serve request (not revoked)
    chosen_key = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("status") == "active":
            chosen_key = k
            break

    # Prepare request log skeleton (must always be written)
    req_id = "stk_rq_" + _ulid()
    req_input = {
        "thought": thought,
        "nextThoughtNeeded": nextThoughtNeeded,
        "thoughtNumber": thoughtNumber,
        "totalThoughts": totalThoughts,
        "isRevision": isRevision,
        "revisesThought": revisesThought,
        "branchFromThought": branchFromThought,
        "branchId": branchId,
        "needsMoreThoughts": needsMoreThoughts,
    }

    # If no usable key, still can't proceed, but must attempt to log only if possible.
    if chosen_key is None:
        latency = int((time.time() - start) * 1000)
        # cannot write request log without api_key_id (non-nullable), so return unauthorized
        return _err("UNAUTHORIZED", "No active API key available to serve request.")

    api_key_id = chosen_key.get("id")
    rpm_limit = chosen_key.get("requests_per_minute_limit")

    # Enforce revoked key
    if chosen_key.get("status") != "active":
        http_status = 403
        resp = _err("UNAUTHORIZED", "API key revoked.")
        latency = int((time.time() - start) * 1000)
        request_logs.append({
            "id": req_id,
            "api_key_id": api_key_id,
            "session_id": None,
            "thought_event_id": None,
            "tool_name": "sequentialthinking",
            "input": req_input,
            "response": resp,
            "http_status": http_status,
            "latency_ms": latency,
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        _save("request_logs.json", request_logs)
        return resp

    # Enforce rate limit (still logs)
    if _rate_limited(request_logs, api_key_id, rpm_limit):
        http_status = 429
        resp = _err("RATE_LIMIT", "Rate limit exceeded.")
        latency = int((time.time() - start) * 1000)
        request_logs.append({
            "id": req_id,
            "api_key_id": api_key_id,
            "session_id": None,
            "thought_event_id": None,
            "tool_name": "sequentialthinking",
            "input": req_input,
            "response": resp,
            "http_status": http_status,
            "latency_ms": latency,
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        _save("request_logs.json", request_logs)
        return resp

    # Find or create active session for this key
    session = None
    for s in sessions:
        if isinstance(s, dict) and s.get("api_key_id") == api_key_id and s.get("status") == "active":
            session = s
            break

    if session is None:
        # enforce max_active_sessions before creating new session
        max_active = chosen_key.get("max_active_sessions")
        if not isinstance(max_active, int) or max_active < 1:
            max_active = 1
        if _active_sessions_count(sessions, api_key_id) >= max_active:
            http_status = 409
            resp = _err("CONFLICT", "Maximum active sessions exceeded.", max_active_sessions=max_active)
            latency = int((time.time() - start) * 1000)
            request_logs.append({
                "id": req_id,
                "api_key_id": api_key_id,
                "session_id": None,
                "thought_event_id": None,
                "tool_name": "sequentialthinking",
                "input": req_input,
                "response": resp,
                "http_status": http_status,
                "latency_ms": latency,
                "created_at": now_iso,
                "updated_at": now_iso,
            })
            _save("request_logs.json", request_logs)
            return resp

        sess_id = "stk_sess_" + _ulid()
        session = {
            "id": sess_id,
            "api_key_id": api_key_id,
            "status": "active",
            "current_branch_id": None,
            "last_thought_number": 0,
            "estimated_total_thoughts": max(1, totalThoughts),
            "completed_at": None,
            "cancelled_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        sessions.append(session)

    session_id = session.get("id")

    # Determine branch context
    branch_external = bnorm  # may be None
    if branch_external is not None and branch_external == "":
        branch_external = None

    # If branchId provided and does not exist, create it (may need to validate branchFromThought)
    if branch_external is not None:
        existing_branch = None
        for br in branches:
            if isinstance(br, dict) and br.get("session_id") == session_id and br.get("branch_id") == branch_external:
                existing_branch = br
                break

        if existing_branch is None:
            # if branchFromThought provided, it must refer to an accepted thought in session
            parent_branch_id = None
            if branchFromThought is not None:
                found = False
                for ev in thought_events:
                    if not isinstance(ev, dict):
                        continue
                    if ev.get("session_id") != session_id:
                        continue
                    if ev.get("status") != "accepted":
                        continue
                    if ev.get("thought_number") != branchFromThought:
                        continue
                    # accepted at branchExternal? requirement: referenced thought must exist as accepted in session
                    found = True
                    parent_branch_id = ev.get("branch_id")
                    break
                if not found:
                    # create rejected thought_event + request_log and return
                    te_id = "stk_tht_" + _ulid()
                    resp = _err("CONFLICT", "Thought event rejected.", rejection_reason="branch_from_thought_not_found", session_id=session_id, thought_event_id=te_id)
                    thought_events.append({
                        "id": te_id,
                        "session_id": session_id,
                        "status": "rejected" if session.get("status") == "active" else "rejected",
                        "thought": thought,
                        "next_thought_needed": nextThoughtNeeded,
                        "needs_more_thoughts": needsMoreThoughts,
                        "thought_number": thoughtNumber,
                        "total_thoughts": totalThoughts,
                        "is_revision": isRevision,
                        "revises_thought_number": revisesThought,
                        "branch_from_thought_number": branchFromThought,
                        "branch_id": branch_external,
                        "rejection_reason": "branch_from_thought_not_found",
                        "created_at": now_iso,
                        "updated_at": now_iso,
                    })
                    latency = int((time.time() - start) * 1000)
                    request_logs.append({
                        "id": req_id,
                        "api_key_id": api_key_id,
                        "session_id": session_id,
                        "thought_event_id": te_id,
                        "tool_name": "sequentialthinking",
                        "input": req_input,
                        "response": resp,
                        "http_status": 409,
                        "latency_ms": latency,
                        "created_at": now_iso,
                        "updated_at": now_iso,
                    })
                    _save("thought_events.json", thought_events)
                    _save("request_logs.json", request_logs)
                    _save("thinking_sessions.json", sessions)
                    _save("branches.json", branches)
                    return resp

            br_row = {
                "id": "stk_br_" + _ulid(),
                "session_id": session_id,
                "branch_id": branch_external,
                "status": "active",
                "parent_branch_id": parent_branch_id,
                "branched_from_thought_number": branchFromThought,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            branches.append(br_row)

    # Create thought event: accepted only if session is active at time of processing
    te_id = "stk_tht_" + _ulid()
    accept_allowed = (session.get("status") == "active")

    rejection_reason = None
    status = "accepted" if accept_allowed else "rejected"
    if not accept_allowed:
        if session.get("status") == "completed":
            rejection_reason = "session_completed"
        elif session.get("status") == "cancelled":
            rejection_reason = "session_cancelled"
        else:
            rejection_reason = "session_not_active"

    # Unique (session_id, branch_id, thought_number)
    if status == "accepted":
        for ev in thought_events:
            if not isinstance(ev, dict):
                continue
            if ev.get("session_id") != session_id:
                continue
            # treat None as default branch; compare directly
            if ev.get("branch_id") != branch_external:
                continue
            if ev.get("thought_number") == thoughtNumber:
                status = "rejected"
                rejection_reason = "duplicate_thought_number"
                break

    # Revision target existence (accepted thought in same session, same branch if branch specified)
    if status == "accepted" and isRevision is True:
        target_found = False
        for ev in thought_events:
            if not isinstance(ev, dict):
                continue
            if ev.get("session_id") != session_id:
                continue
            if ev.get("status") != "accepted":
                continue
            if branch_external is not None and ev.get("branch_id") != branch_external:
                continue
            if ev.get("thought_number") == revisesThought:
                target_found = True
                break
        if not target_found:
            # Real-world behavior: allow "future revision target" sometimes, but business rule says must exist.
            status = "rejected"
            rejection_reason = "revision_target_not_found"

    te_row = {
        "id": te_id,
        "session_id": session_id,
        "status": status,
        "thought": thought,
        "next_thought_needed": nextThoughtNeeded,
        "needs_more_thoughts": needsMoreThoughts,
        "thought_number": thoughtNumber,
        "total_thoughts": totalThoughts,
        "is_revision": isRevision,
        "revises_thought_number": revisesThought if isRevision else None,
        "branch_from_thought_number": branchFromThought,
        "branch_id": branch_external,
        "rejection_reason": rejection_reason if status == "rejected" else None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    thought_events.append(te_row)

    # If accepted, update session fields
    if status == "accepted":
        # update estimated_total_thoughts to max seen accepted for session
        try:
            cur_est = int(session.get("estimated_total_thoughts") or 1)
        except Exception:
            cur_est = 1
        session["estimated_total_thoughts"] = max(cur_est, totalThoughts)
        # update last_thought_number to max accepted overall
        try:
            cur_last = int(session.get("last_thought_number") or 0)
        except Exception:
            cur_last = 0
        session["last_thought_number"] = max(cur_last, thoughtNumber)
        # current branch id set to provided branch or keep as-is
        if branch_external is not None:
            session["current_branch_id"] = branch_external
        session["updated_at"] = now_iso

        # Completion transition if nextThoughtNeeded is false OR needsMoreThoughts is explicitly false
        should_complete = (nextThoughtNeeded is False) or (needsMoreThoughts is False)
        if should_complete and session.get("status") == "active":
            # lifecycle transition active -> completed only
            session["status"] = "completed"
            session["completed_at"] = now_iso
            session["updated_at"] = now_iso

    # Persist all changes
    _save("thinking_sessions.json", sessions)
    _save("thought_events.json", thought_events)
    _save("branches.json", branches)

    # Prepare response
    if status == "accepted":
        http_status = 200
        resp = {
            "session": session,
            "thought_event": te_row,
        }
    else:
        http_status = 409
        resp = _err("CONFLICT", "Thought event rejected.", rejection_reason=rejection_reason, session_id=session_id, thought_event_id=te_id)

    latency = int((time.time() - start) * 1000)
    request_logs.append({
        "id": req_id,
        "api_key_id": api_key_id,
        "session_id": session_id,
        "thought_event_id": te_id,
        "tool_name": "sequentialthinking",
        "input": req_input,
        "response": resp,
        "http_status": http_status,
        "latency_ms": latency,
        "created_at": now_iso,
        "updated_at": now_iso,
    })
    _save("request_logs.json", request_logs)
    return resp

def sequentialthinking_getSession(sessionId=None, includeThoughts=None, thoughtsLimit=None, branchId=None, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0551000" if __import__("os").path.isdir("./environment_mix/0551000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    _C32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid():
        ms = int(time.time() * 1000)
        t = ms
        chars = []
        for _ in range(10):
            chars.append(_C32[t & 31])
            t >>= 5
        ts = "".join(reversed(chars))
        r = random.getrandbits(80)
        chars = []
        for _ in range(16):
            chars.append(_C32[r & 31])
            r >>= 5
        rs = "".join(reversed(chars))
        return ts + rs

    start = time.time()
    now = _now()

    api_keys = _load("api_keys.json")
    sessions = _load("thinking_sessions.json")
    thought_events = _load("thought_events.json")
    request_logs = _load("request_logs.json")

    # Defaults
    if includeThoughts is None:
        includeThoughts = False
    if thoughtsLimit is None:
        thoughtsLimit = 50

    # Validate
    if sessionId is not None and not isinstance(sessionId, str):
        return _err("VALIDATION_ERROR", "sessionId must be a string when provided.")
    if not isinstance(includeThoughts, bool):
        return _err("VALIDATION_ERROR", "includeThoughts must be boolean.")
    if not isinstance(thoughtsLimit, int) or thoughtsLimit < 1 or thoughtsLimit > 500:
        return _err("VALIDATION_ERROR", "thoughtsLimit must be an integer between 1 and 500.")
    if branchId is not None and (not isinstance(branchId, str) or not branchId.strip()):
        return _err("VALIDATION_ERROR", "branchId must be a non-empty string when provided.")

    # Resolve a working key for this read respecting RPM
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        return _err("UNAUTHORIZED", "No active API key available for this request.")

    chosen_key = None
    for k in active_keys:
        rpm = k.get("requests_per_minute_limit")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 6000:
            continue
        cutoff = now - datetime.timedelta(seconds=60)
        cnt = 0
        kid = k.get("id")
        for rl in request_logs:
            if not isinstance(rl, dict):
                continue
            if rl.get("api_key_id") != kid:
                continue
            ts = _parse_iso(rl.get("created_at"))
            if ts is None:
                continue
            if ts >= cutoff:
                cnt += 1
        if cnt < rpm:
            chosen_key = k
            break

    if chosen_key is None:
        k0 = active_keys[0]
        latency = int((time.time() - start) * 1000)
        resp = _err("RATE_LIMIT", "Rate limit exceeded.")
        request_logs.append({
            "id": _ulid(),
            "api_key_id": k0.get("id"),
            "session_id": None,
            "thought_event_id": None,
            "tool_name": "sequentialthinking",
            "input": {"sessionId": sessionId, "includeThoughts": includeThoughts, "thoughtsLimit": thoughtsLimit, "branchId": branchId},
            "response": resp,
            "http_status": 429,
            "latency_ms": max(0, latency),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("request_logs.json", request_logs)
        return resp

    api_key_id = chosen_key.get("id")

    # Find session
    sess = None
    if sessionId is not None:
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == sessionId and s.get("api_key_id") == api_key_id:
                sess = s
                break
        if sess is None:
            # log + return NOT_FOUND (mutation rule doesn't apply; but here a read by id should 404)
            latency = int((time.time() - start) * 1000)
            resp = _err("NOT_FOUND", "Session not found.")
            request_logs.append({
                "id": _ulid(),
                "api_key_id": api_key_id,
                "session_id": None,
                "thought_event_id": None,
                "tool_name": "sequentialthinking",
                "input": {"sessionId": sessionId, "includeThoughts": includeThoughts, "thoughtsLimit": thoughtsLimit, "branchId": branchId},
                "response": resp,
                "http_status": 404,
                "latency_ms": max(0, latency),
                "created_at": _iso(now),
                "updated_at": _iso(now),
            })
            _save("request_logs.json", request_logs)
            return resp
    else:
        # current active session
        for s in sessions:
            if isinstance(s, dict) and s.get("api_key_id") == api_key_id and s.get("status") == "active":
                sess = s
                break
        # If none, return empty (normal envelope)
        if sess is None:
            resp = {"session": None}
            latency = int((time.time() - start) * 1000)
            request_logs.append({
                "id": _ulid(),
                "api_key_id": api_key_id,
                "session_id": None,
                "thought_event_id": None,
                "tool_name": "sequentialthinking",
                "input": {"sessionId": sessionId, "includeThoughts": includeThoughts, "thoughtsLimit": thoughtsLimit, "branchId": branchId},
                "response": resp,
                "http_status": 200,
                "latency_ms": max(0, latency),
                "created_at": _iso(now),
                "updated_at": _iso(now),
            })
            _save("request_logs.json", request_logs)
            return resp

    resp = {"session": sess}

    if includeThoughts:
        sid = sess.get("id")
        evs = []
        for ev in thought_events:
            if not isinstance(ev, dict):
                continue
            if ev.get("session_id") != sid:
                continue
            if branchId is not None:
                if ev.get("branch_id") != branchId:
                    continue
            evs.append(ev)
        # order by created_at desc
        evs.sort(key=lambda r: (_parse_iso(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=True)
        evs = evs[:thoughtsLimit]
        resp["thoughts"] = evs
        resp["thoughts_count"] = len(evs)

    latency = int((time.time() - start) * 1000)
    request_logs.append({
        "id": _ulid(),
        "api_key_id": api_key_id,
        "session_id": sess.get("id"),
        "thought_event_id": None,
        "tool_name": "sequentialthinking",
        "input": {"sessionId": sessionId, "includeThoughts": includeThoughts, "thoughtsLimit": thoughtsLimit, "branchId": branchId},
        "response": resp,
        "http_status": 200,
        "latency_ms": max(0, latency),
        "created_at": _iso(now),
        "updated_at": _iso(now),
    })
    _save("request_logs.json", request_logs)
    return resp

def sequentialthinking_listSessions(status=None, limit=None, cursor=None, createdAfter=None, createdBefore=None, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0551000" if __import__("os").path.isdir("./environment_mix/0551000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _C32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid():
        ms = int(time.time() * 1000)
        t = ms
        out = []
        for _ in range(10):
            out.append(_C32[t & 31]); t >>= 5
        ts = "".join(reversed(out))
        r = random.getrandbits(80)
        out = []
        for _ in range(16):
            out.append(_C32[r & 31]); r >>= 5
        rs = "".join(reversed(out))
        return ts + rs

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log_request(request_logs, api_key_id, http_status, tool_input, response_obj, latency_ms):
        now = _now_iso()
        request_logs.append({
            "id": "stk_req_" + _ulid(),
            "api_key_id": api_key_id,
            "session_id": None,
            "thought_event_id": None,
            "tool_name": "sequentialthinking",
            "input": tool_input,
            "response": response_obj,
            "http_status": int(http_status),
            "latency_ms": int(max(0, min(300000, latency_ms))),
            "created_at": now,
            "updated_at": now,
        })

    def _rate_limited(request_logs, api_key_id, rpm_limit):
        if not isinstance(rpm_limit, int) or rpm_limit < 1:
            return True
        now = datetime.datetime.now(datetime.timezone.utc)
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in request_logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            ts = _parse_iso(r.get("created_at"))
            if ts is None:
                continue
            if ts >= window_start:
                cnt += 1
        return cnt >= rpm_limit

    t0 = time.time()

    api_keys = _load("api_keys.json")
    sessions = _load("thinking_sessions.json")
    request_logs = _load("request_logs.json")

    tool_input = {
        "status": status,
        "limit": limit,
        "cursor": cursor,
        "createdAfter": createdAfter,
        "createdBefore": createdBefore,
    }

    # Ambient auth context
    active_key = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"), None)
    any_key = active_key or next((k for k in api_keys if isinstance(k, dict) and isinstance(k.get("id"), str)), None)
    if any_key is None:
        return _err("UNAUTHORIZED", "No API key context available.")
    api_key_id = any_key.get("id")

    # Rate limit before processing
    if _rate_limited(request_logs, api_key_id, any_key.get("requests_per_minute_limit")):
        latency_ms = int((time.time() - t0) * 1000)
        resp = _err("RATE_LIMIT", "Rate limit exceeded.")
        _log_request(request_logs, api_key_id, 429, tool_input, resp, latency_ms)
        _save("request_logs.json", request_logs)
        return resp

    # If revoked refuse, but still log
    if any_key.get("status") == "revoked":
        latency_ms = int((time.time() - t0) * 1000)
        resp = _err("UNAUTHORIZED", "API key is revoked.")
        _log_request(request_logs, api_key_id, 403, tool_input, resp, latency_ms)
        _save("request_logs.json", request_logs)
        return resp

    if limit is None:
        limit = 50

    if status is not None and status not in ("active", "completed", "cancelled"):
        latency_ms = int((time.time() - t0) * 1000)
        resp = _err("VALIDATION_ERROR", "Invalid status filter.")
        _log_request(request_logs, api_key_id, 400, tool_input, resp, latency_ms)
        _save("request_logs.json", request_logs)
        return resp
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        latency_ms = int((time.time() - t0) * 1000)
        resp = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
        _log_request(request_logs, api_key_id, 400, tool_input, resp, latency_ms)
        _save("request_logs.json", request_logs)
        return resp
    if cursor is not None and not isinstance(cursor, str):
        latency_ms = int((time.time() - t0) * 1000)
        resp = _err("VALIDATION_ERROR", "cursor must be a string when provided.")
        _log_request(request_logs, api_key_id, 400, tool_input, resp, latency_ms)
        _save("request_logs.json", request_logs)
        return resp

    # createdAfter/createdBefore are documented as RFC3339, but relax validation:
    # if unparsable, treat as absent rather than error (matches audit requirement).
    ca = _parse_iso(createdAfter) if isinstance(createdAfter, str) else None
    cb = _parse_iso(createdBefore) if isinstance(createdBefore, str) else None

    # Filter to caller key
    rows = [s for s in sessions if isinstance(s, dict) and s.get("api_key_id") == api_key_id]

    if status is not None:
        rows = [s for s in rows if s.get("status") == status]

    if ca is not None:
        tmp = []
        for s in rows:
            ts = _parse_iso(s.get("created_at"))
            if ts is not None and ts > ca:
                tmp.append(s)
        rows = tmp

    if cb is not None:
        tmp = []
        for s in rows:
            ts = _parse_iso(s.get("created_at"))
            if ts is not None and ts < cb:
                tmp.append(s)
        rows = tmp

    # Sort by updated_at desc (fallback created_at)
    def _sort_key(s):
        ts = _parse_iso(s.get("updated_at")) or _parse_iso(s.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return ts
    rows.sort(key=_sort_key, reverse=True)

    # Cursor: opaque string; implement as "after_id:<session_id>" OR accept raw session_id
    start_idx = 0
    if cursor:
        cur_id = None
        if cursor.startswith("after_id:"):
            cur_id = cursor.split("after_id:", 1)[1]
        else:
            cur_id = cursor
        for i, s in enumerate(rows):
            if s.get("id") == cur_id:
                start_idx = i + 1
                break

    page = rows[start_idx:start_idx + limit]
    has_more = (start_idx + limit) < len(rows)
    next_cursor = ("after_id:" + page[-1]["id"]) if (has_more and page) else None

    resp = {
        "data": page,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        }
    }

    latency_ms = int((time.time() - t0) * 1000)
    _log_request(request_logs, api_key_id, 200, tool_input, resp, latency_ms)
    _save("request_logs.json", request_logs)
    return resp

def sequentialthinking_completeSession(sessionId=None, reason=None, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0551000" if __import__("os").path.isdir("./environment_mix/0551000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    _C32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid():
        ms = int(time.time() * 1000)
        t = ms
        chars = []
        for _ in range(10):
            chars.append(_C32[t & 31])
            t >>= 5
        ts = "".join(reversed(chars))
        r = random.getrandbits(80)
        chars = []
        for _ in range(16):
            chars.append(_C32[r & 31])
            r >>= 5
        rs = "".join(reversed(chars))
        return ts + rs

    start = time.time()
    now = _now()

    # Validate inputs
    if sessionId is not None and not isinstance(sessionId, str):
        return _err("VALIDATION_ERROR", "sessionId must be a string when provided.")
    if reason is not None and not isinstance(reason, str):
        return _err("VALIDATION_ERROR", "reason must be a string when provided.")

    api_keys = _load("api_keys.json")
    sessions = _load("thinking_sessions.json")
    request_logs = _load("request_logs.json")

    # Resolve a working key respecting RPM
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        return _err("UNAUTHORIZED", "No active API key available for this request.")

    chosen_key = None
    for k in active_keys:
        rpm = k.get("requests_per_minute_limit")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 6000:
            continue
        cutoff = now - datetime.timedelta(seconds=60)
        cnt = 0
        kid = k.get("id")
        for rl in request_logs:
            if not isinstance(rl, dict):
                continue
            if rl.get("api_key_id") != kid:
                continue
            ts = _parse_iso(rl.get("created_at"))
            if ts is None:
                continue
            if ts >= cutoff:
                cnt += 1
        if cnt < rpm:
            chosen_key = k
            break

    if chosen_key is None:
        k0 = active_keys[0]
        latency = int((time.time() - start) * 1000)
        resp = _err("RATE_LIMIT", "Rate limit exceeded.")
        request_logs.append({
            "id": _ulid(),
            "api_key_id": k0.get("id"),
            "session_id": None,
            "thought_event_id": None,
            "tool_name": "sequentialthinking",
            "input": {"sessionId": sessionId, "reason": reason},
            "response": resp,
            "http_status": 429,
            "latency_ms": max(0, latency),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("request_logs.json", request_logs)
        return resp

    api_key_id = chosen_key.get("id")

    # Find target session
    target = None
    if sessionId is not None:
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == sessionId and s.get("api_key_id") == api_key_id:
                target = s
                break
        if target is None:
            latency = int((time.time() - start) * 1000)
            resp = _err("NOT_FOUND", "Session not found.")
            request_logs.append({
                "id": _ulid(),
                "api_key_id": api_key_id,
                "session_id": None,
                "thought_event_id": None,
                "tool_name": "sequentialthinking",
                "input": {"sessionId": sessionId, "reason": reason},
                "response": resp,
                "http_status": 404,
                "latency_ms": max(0, latency),
                "created_at": _iso(now),
                "updated_at": _iso(now),
            })
            _save("request_logs.json", request_logs)
            return resp
    else:
        for s in sessions:
            if isinstance(s, dict) and s.get("api_key_id") == api_key_id and s.get("status") == "active":
                target = s
                break
        if target is None:
            latency = int((time.time() - start) * 1000)
            resp = _err("NOT_FOUND", "No active session to complete.")
            request_logs.append({
                "id": _ulid(),
                "api_key_id": api_key_id,
                "session_id": None,
                "thought_event_id": None,
                "tool_name": "sequentialthinking",
                "input": {"sessionId": sessionId, "reason": reason},
                "response": resp,
                "http_status": 404,
                "latency_ms": max(0, latency),
                "created_at": _iso(now),
                "updated_at": _iso(now),
            })
            _save("request_logs.json", request_logs)
            return resp

    # Enforce transition
    if target.get("status") != "active":
        latency = int((time.time() - start) * 1000)
        resp = _err("INVALID_TRANSITION", "Session is not active and cannot be completed.", status=target.get("status"))
        request_logs.append({
            "id": _ulid(),
            "api_key_id": api_key_id,
            "session_id": target.get("id"),
            "thought_event_id": None,
            "tool_name": "sequentialthinking",
            "input": {"sessionId": sessionId, "reason": reason},
            "response": resp,
            "http_status": 409,
            "latency_ms": max(0, latency),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("request_logs.json", request_logs)
        return resp

    # Apply completion
    target["status"] = "completed"
    target["completed_at"] = _iso(now)
    target["updated_at"] = _iso(now)

    _save("thinking_sessions.json", sessions)

    resp = {"session": target, "reason": reason}

    latency = int((time.time() - start) * 1000)
    request_logs.append({
        "id": _ulid(),
        "api_key_id": api_key_id,
        "session_id": target.get("id"),
        "thought_event_id": None,
        "tool_name": "sequentialthinking",
        "input": {"sessionId": sessionId, "reason": reason},
        "response": resp,
        "http_status": 200,
        "latency_ms": max(0, latency),
        "created_at": _iso(now),
        "updated_at": _iso(now),
    })
    _save("request_logs.json", request_logs)
    return resp

def sequentialthinking_listThoughtEvents(sessionId, branchId=None, status=None, limit=None, cursor=None, fromThoughtNumber=None, **_extra):
    import json, os, datetime, time, random, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0551000" if __import__("os").path.isdir("./environment_mix/0551000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid():
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        r = random.getrandbits(80)
        v = (ms << 80) | r
        out = []
        for _ in range(26):
            out.append(alphabet[v & 31])
            v >>= 5
        return "".join(reversed(out))

    def _find_working_api_key(api_keys):
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    api_keys = _load("api_keys.json")
    sessions = _load("thinking_sessions.json")
    events = _load("thought_events.json")
    logs = _load("request_logs.json")

    api_key = _find_working_api_key(api_keys)
    if api_key is None:
        http_status = 401
        resp = _err("UNAUTHORIZED", "API key missing or revoked.")
        revoked = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "revoked"), None)
        if revoked is not None:
            rid = _ulid()
            logs.append({
                "id": rid,
                "api_key_id": revoked.get("id"),
                "session_id": sessionId if isinstance(sessionId, str) else None,
                "thought_event_id": None,
                "tool_name": "sequentialthinking",
                "input": {"tool": "sequentialthinking_listThoughtEvents", "sessionId": sessionId, "branchId": branchId, "status": status, "limit": limit, "cursor": cursor, "fromThoughtNumber": fromThoughtNumber},
                "response": resp,
                "http_status": http_status,
                "latency_ms": max(0, min(300000, int((time.time() - t0) * 1000))),
                "created_at": now,
                "updated_at": now,
            })
            _save("request_logs.json", logs)
        return resp

    # Validate inputs
    resp = None
    http_status = None

    if not isinstance(sessionId, str) or not sessionId:
        resp = _err("VALIDATION_ERROR", "sessionId is required and must be a non-empty string.", field="sessionId")
        http_status = 400
    elif branchId is not None and not isinstance(branchId, str):
        resp = _err("VALIDATION_ERROR", "branchId must be a string when provided.", field="branchId")
        http_status = 400
    elif status is not None and status not in ("accepted", "rejected"):
        resp = _err("VALIDATION_ERROR", "status must be one of: accepted, rejected.", field="status")
        http_status = 400
    else:
        if limit is None:
            limit = 100
        if not isinstance(limit, int):
            resp = _err("VALIDATION_ERROR", "limit must be an integer.", field="limit")
            http_status = 400
        elif limit < 1 or limit > 500:
            resp = _err("VALIDATION_ERROR", "limit must be between 1 and 500.", field="limit")
            http_status = 400
        elif fromThoughtNumber is not None and (not isinstance(fromThoughtNumber, int) or fromThoughtNumber < 1):
            resp = _err("VALIDATION_ERROR", "fromThoughtNumber must be an integer >= 1 when provided.", field="fromThoughtNumber")
            http_status = 400
        elif cursor is not None and not isinstance(cursor, str):
            resp = _err("VALIDATION_ERROR", "cursor must be a string when provided.", field="cursor")
            http_status = 400

    # Rate limit check (rolling 60s window)
    if resp is None:
        limit_rpm = api_key.get("requests_per_minute_limit")
        if not isinstance(limit_rpm, int) or limit_rpm < 1 or limit_rpm > 6000:
            resp = _err("VALIDATION_ERROR", "API key requests_per_minute_limit is invalid.")
            http_status = 500
        else:
            window_start = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("api_key_id") != api_key.get("id"):
                    continue
                ts = r.get("created_at")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).astimezone(datetime.timezone.utc).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= window_start:
                    cnt += 1
            if cnt >= limit_rpm:
                resp = _err("RATE_LIMIT", "Rate limit exceeded.")
                http_status = 429

    if resp is None and api_key.get("status") == "revoked":
        resp = _err("UNAUTHORIZED", "API key revoked.")
        http_status = 403

    session = None
    if resp is None:
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == sessionId and s.get("api_key_id") == api_key.get("id"):
                session = s
                break
        if session is None:
            resp = _err("NOT_FOUND", "Session not found for this API key.")
            http_status = 404

    # Cursor decode: base64url of JSON {"offset": int}
    offset = 0
    if resp is None and cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"==")
            obj = json.loads(raw.decode("utf-8"))
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                resp = _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
                http_status = 400
            else:
                offset = off
        except Exception:
            resp = _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            http_status = 400

    out = None
    if resp is None:
        rows = []
        for e in events:
            if not isinstance(e, dict):
                continue
            if e.get("session_id") != sessionId:
                continue
            if branchId is not None:
                if e.get("branch_id") != branchId:
                    continue
            if status is not None and e.get("status") != status:
                continue
            tn = e.get("thought_number")
            if fromThoughtNumber is not None:
                if not isinstance(tn, int) or tn < fromThoughtNumber:
                    continue
            rows.append(e)

        # Order by (branch_id, thought_number asc, created_at asc)
        def _k(e):
            b = e.get("branch_id")
            b = "" if b is None else str(b)
            tn = e.get("thought_number")
            tn = tn if isinstance(tn, int) else 10**18
            ca = e.get("created_at") or ""
            return (b, tn, ca, e.get("id") or "")
        rows.sort(key=_k)

        total = len(rows)
        page = rows[offset: offset + limit]
        next_offset = offset + len(page)
        has_more = next_offset < total
        next_cursor = None
        if has_more:
            payload = json.dumps({"offset": next_offset}, separators=(",", ":")).encode("utf-8")
            next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

        out = {
            "session_id": sessionId,
            "events": page,
            "pagination": {
                "total": total,
                "limit": limit,
                "cursor": cursor,
                "next_cursor": next_cursor,
                "has_more": has_more,
                "offset": offset
            }
        }
        resp = out
        http_status = 200

    # Log request
    rid = _ulid()
    latency_ms = max(0, min(300000, int((time.time() - t0) * 1000)))
    logs.append({
        "id": rid,
        "api_key_id": api_key.get("id"),
        "session_id": sessionId if isinstance(sessionId, str) else None,
        "thought_event_id": None,
        "tool_name": "sequentialthinking",
        "input": {"tool": "sequentialthinking_listThoughtEvents", "sessionId": sessionId, "branchId": branchId, "status": status, "limit": limit, "cursor": cursor, "fromThoughtNumber": fromThoughtNumber},
        "response": resp,
        "http_status": int(http_status if http_status is not None else 500),
        "latency_ms": latency_ms,
        "created_at": now,
        "updated_at": now,
    })
    _save("request_logs.json", logs)

    return resp
